#include "fractal/desktop_client_core.h"
#include <string.h>
static fractal_intent_id iid(uint64_t n){fractal_intent_id id={0x434d440000000000ull,n};return id;}
static fractal_client_intent intent(fractal_local_service*s,fractal_participant_id p,uint64_t seq,fractal_client_intent_kind k){fractal_client_intent i;memset(&i,0,sizeof(i));i.contract_version=FRACTAL_WORKSPACE_CONTRACT_VERSION;i.workspace_id=s->workspace.id;i.participant_id=p;i.expected_revision=s->workspace.revision;i.command_sequence=seq;i.kind=k;i.identity=iid(seq);return i;}
int fractal_desktop_client_run_reference_scenario(fractal_desktop_client_summary*out){fractal_local_service s;fractal_participant_id p;fractal_client_intent a,b;fractal_local_transition_result r1,r2;fractal_reacquire_request q;fractal_reacquire_response rr;if(!out)return-1;memset(out,0,sizeof(*out));fractal_local_service_init(&s,1u);if(fractal_local_service_open(&s)!=0)return-1;out->compatibility_ok=true;if(fractal_local_service_open_session(&s,fractal_local_operator_admit_current_user(),&p)!=0)return-1;out->session_ok=true;a=intent(&s,p,1u,FRACTAL_INTENT_ACQUIRE_LEASE);r1=fractal_local_service_apply_intent(&s,&a);if(!r1.transition.accepted)return-1;b=intent(&s,p,2u,FRACTAL_INTENT_SET_ITERATION_BUDGET);b.payload.unsigned_value=128u;r1=fractal_local_service_apply_intent(&s,&b);r2=fractal_local_service_apply_intent(&s,&b);out->replay_explicit=r2.replay_kind==FRACTAL_REPLAY_IDENTICAL_RESULT&&r2.transition.resulting_revision==r1.transition.resulting_revision;memset(&q,0,sizeof(q));q.contract_version=FRACTAL_REACQUIRE_CONTRACT_VERSION;q.service_id=s.service_id;q.participant_id=p;q.workspace_id=s.workspace.id;q.last_accepted_workspace_revision=s.workspace.revision-1u;q.last_known_generation=0u;rr=fractal_local_service_reacquire(&s,&q);out->reacquired=rr.kind==FRACTAL_REACQUIRE_FULL_SNAPSHOT;out->revision=s.workspace.revision;out->generation=s.workspace.generation.number;out->semantic_digest=fractal_local_semantic_digest(&s);out->semantic_drift=0u;return 0;}
